import { arrayAdd } from "./array";
import { ENTRIES, ERROR, LENGTH, NEW_LINE } from "./constants";
import { hasProp, newMap, newSet, O } from "./object";
import { replace } from "./string";
import { isArray, isInstance, isMap, isNull, isObject, isSet, isUndefined } from "./typeCheck";

/**
 * Determines whether an string or array includes a certain value
 * @param value the string or array to search
 * @param item the value to search for
 * @param position the position to start the search
 * @returns true if the value is found, else false
 */
export let has = (value: string|any[], item: any, position?: number) =>
    value.includes(item, position);

export let entries = (value: any): [string | number, any][] =>
    isObject(value) ? O[ENTRIES](value) : value[ENTRIES]();

/**
 * Returns a section of a string or a copy of a section of an array
 * @param value the string or array to take a slice from
 * @param start the index to start the slice
 * @param end the index to end the slice
 * @returns the slice of the string or array
 */
export let slice = (value: string|any[], start?: number | undefined, end?: number | undefined) =>
    value.slice(start, end);

/** Returns the size/length of a value */
export let size = (value: any): number => isUndefined(value[LENGTH]) ? value.size : value[LENGTH];

export let wait = (callback: FunctionType, ms = 0) => setTimeout(callback, ms);

export let clearWait = (id: number) => {
    clearTimeout(id);
}

export let waitAsync = (callback: FunctionType, ms = 0) => new Promise(resolve => wait(() => resolve(callback()), ms));

/**
 * Debounce: the callback function will only be called after the delay has passed since the last call.
 * @param callback Function to debounce
 * @param delay Time to wait before calling the function
 * @returns A debounced function
 */
export let debounce = (callback: Function, delay?: number) => {
    let timeout: any;
    return (...args: any[]) => {
        clearWait(timeout);
        timeout = wait(() => callback(...args), delay);
    }
}

/**
 * Throttle: the callback function will only be called once every delay milliseconds.
 * @param callback Function to throttle
 * @param delay Time to wait before calling the function
 * @returns A throttled function
 */
export let throttle = (callback: Function, delay: number) => {
    let last: number = 0;
    return (...args: any[]) => {
        let now = Date.now();
        if (now - last < delay) return;
        last = now;
        return callback(...args);
    }
}

let _uids: ObjectType = {};

let _uid = (length: number) => slice(replace(crypto.randomUUID(), /-/g, ''), 0, length - 1) as string;

/**
 * Generates a unique string of a minimum length.
 * @param length
 */
export let uid = (length: number = 8): string => {
    let key = _uid(length);

    // Make sure the key is unique.
    // If the key has been used, generate a new, longer key
    while (key in _uids) key = _uid(size(key) + 1);

    // Mark the key as used
    _uids[key] = true;

    return 'b' + key;
}

/**
 * Logs a message.
 * @returns Brio.js `...details`
 */
export let log = (type: 'log'|'warn'|'error', ...details: any[]): any => console[type]('Brio.js', ...details);

/**
 * Logs a warning message.
 * @returns Brio.js warn: `...details`
 */
export let logWarn = (...details: any[]) => log('warn', 'warn:', NEW_LINE, ...details);

/**
 * Logs an error message.
 * @returns Brio.js detected an error: `...details`
 */
export let logError = (...details: any[]) => log(ERROR, `detected an ${ERROR}:`, NEW_LINE, ...details);


export let deepClone = (value: any, seen = new WeakMap()) => {
  // Handle primitives and functions (returned as-is)
  if (isNull(value) || typeof value !== 'object') {
    return value;
  }

  // Handle circular references
  if (seen.has(value)) {
    return seen.get(value);
  }

  let cloned: any;

  // Handle plain Object
  if (isObject(value)) {
    cloned = {};
    seen.set(value, cloned);
    for (let key in value) {
      if (hasProp(value, key)) {
        cloned[key] = deepClone(value[key], seen);
      }
    }
  }

  // Handle Array
  else if (isArray(value)) {
    cloned = [];
    seen.set(value, cloned);
    for (let item of value) {
      arrayAdd(cloned, deepClone(item, seen));
    }
  }

  // Handle Map
  else if (isMap(value)) {
    cloned = newMap();
    seen.set(value, cloned);
    for (let [key, val] of entries(value)) {
      cloned.set(deepClone(key, seen), deepClone(val, seen));
    }
  }

  // Handle Set
  else if (isSet(value)) {
    cloned = newSet();
    seen.set(value, cloned);
    for (let item of value.values()) {
      cloned.add(deepClone(item, seen));
    }
  }

  // Handle Date
  else if (isInstance(value, Date)) {
    value = new Date(value);
  }

  // Fallback for unsupported types (e.g., RegExp, Function)
  return value;
}
